export class SessionScopedCache {
    currentGeneration;
    now;
    load;
    #cached = null;
    #inFlight = null;
    constructor(currentGeneration, now, load){
        this.currentGeneration = currentGeneration;
        this.now = now;
        this.load = load;
    }
    get(cacheMs) {
        const generation = this.currentGeneration();
        if (this.#cached?.generation === generation && this.#cached.expiresAt > this.now()) {
            return Promise.resolve(this.#cached.value);
        }
        if (this.#inFlight?.generation === generation) {
            return this.#inFlight.promise;
        }
        let promise;
        try {
            promise = Promise.resolve(this.load());
        } catch (error) {
            promise = Promise.reject(error);
        }
        promise = promise.then((value)=>{
            if (this.currentGeneration() === generation && this.#inFlight?.promise === promise) {
                this.#cached = {
                    generation,
                    expiresAt: this.now() + cacheMs,
                    value
                };
            }
            return value;
        }).finally(()=>{
            if (this.#inFlight?.promise === promise) this.#inFlight = null;
        });
        this.#inFlight = {
            generation,
            promise
        };
        return promise;
    }
    reset() {
        this.#cached = null;
        this.#inFlight = null;
    }
}
